/**
 * The view entity's dialect tables. "Views" are three terraform resource
 * types owned inline by an app (like fields, not an independent lifecycle
 * like agents/automations): `elementum_layout` (one per stage),
 * `elementum_list_view` (a saved list), and `elementum_managed_view_order`
 * (the ordering of an aspect's list views — a singleton once any exist).
 *
 * Unlike field/agent-tool, these three are structurally distinct resources
 * rather than variants of one shape, so there is no typeKey/resourceType
 * dispatch row per kind — just the three resource-type constants plus the
 * layout section-type enum (a nested attribute, not a separate resource).
 */
export declare const LAYOUT_RESOURCE_TYPE = "elementum_layout";
export declare const LIST_VIEW_RESOURCE_TYPE = "elementum_list_view";
export declare const AGENT_VIEW_RESOURCE_TYPE = "elementum_agent_view";
export declare const CALENDAR_VIEW_RESOURCE_TYPE = "elementum_calendar_view";
export declare const KANBAN_VIEW_RESOURCE_TYPE = "elementum_kanban_view";
export declare const DASHBOARD_VIEW_RESOURCE_TYPE = "elementum_dashboard_view";
export declare const MANAGED_VIEW_ORDER_RESOURCE_TYPE = "elementum_managed_view_order";
/**
 * Layout section `type` discriminator: authoring camelCase ↔ the provider's
 * wire value, verified against `provider/internal/provider/layout_resource.go`
 * (the schema's own embedded doc table). Only `group` carries
 * `name`/`icon`/`color`/`field_ids`; `update` additionally takes an optional
 * `name`; the rest are bare component sections.
 */
export declare const SECTION_TYPE_TO_WIRE: Readonly<Record<string, string>>;
export declare const SECTION_TYPE_FROM_WIRE: ReadonlyMap<string, string>;
/** Section types whose `field_ids`/`name`/`icon`/`color` this pass authors (only `group`). */
export declare const GROUP_SECTION_WIRE_TYPE = "group";
/** The one other section type carrying an (optional) `name`. */
export declare const UPDATE_SECTION_WIRE_TYPE = "update";
/**
 * System-field keys the platform refuses to accept in a layout `group`
 * section's `field_ids` on create — confirmed live against `prestonhigh`:
 * `elementum_layout` create errors "cannot place system fields in layout
 * sections: ID (has HANDLE, TITLE, or STATUS tag), Title (...), Status
 * (...)". The platform's OWN auto-provisioned default "System" section
 * legitimately contains them (so `ei export`/`layoutFromTf` still capture
 * them faithfully — this is a real, current fact about the app), but
 * terraform can never re-create a section containing them: `to-tf` must
 * drop these three specifically wherever a group section names them, or
 * every layout recreate (any `sections` edit forces a full replace) fails.
 * Audit fields (createdAt/createdBy/updatedAt/updatedBy/closedAt/closedBy)
 * are NOT restricted — only HANDLE/TITLE/STATUS.
 */
export declare const LAYOUT_RESTRICTED_SYSTEM_FIELD_KEYS: ReadonlySet<string>;
/**
 * System-field key → the `local.<ns>_<attr>` name `entities/app/locals.ts`
 * emits for it (`SYSTEM_FIELD_ID_ATTRS`'s `<tfLabel>_field_id` shape there).
 * Derived, not hand-copied, so a change to `SYSTEM_FIELD_KEYS` can't drift
 * silently out of sync with this table.
 */
export declare const SYSTEM_FIELD_ID_ATTR_BY_KEY: ReadonlyMap<string, string>;
export declare const SYSTEM_FIELD_KEY_BY_ID_ATTR: ReadonlyMap<string, string>;
/** Attributes `layoutFromTf` understands — anything else is dialect growth, reported loudly. */
export declare const KNOWN_LAYOUT_ATTRS: ReadonlySet<string>;
export declare const KNOWN_LAYOUT_SECTION_ATTRS: ReadonlySet<string>;
/** Attributes `listViewFromTf` understands. */
export declare const KNOWN_LIST_VIEW_ATTRS: ReadonlySet<string>;
export declare const KNOWN_AGENT_VIEW_ATTRS: ReadonlySet<string>;
export declare const KNOWN_CALENDAR_VIEW_ATTRS: ReadonlySet<string>;
export declare const KNOWN_KANBAN_VIEW_ATTRS: ReadonlySet<string>;
export declare const KNOWN_DASHBOARD_VIEW_ATTRS: ReadonlySet<string>;
/** Attributes `managedViewOrderFromTf` understands. */
export declare const KNOWN_MANAGED_VIEW_ORDER_ATTRS: ReadonlySet<string>;
